// The input is controlled, so the stories keep the value in local state and let onChange update it.
// The onChange arg (a spy) is still called, so typing shows up in the Actions panel.
const InteractiveInputField = (props: InputFieldProps) => {
  const [value, setValue] = useState(props.value);
  return (
    <InputField
      {...props}
      value={value}
      onChange={(name, newValue) => {
        setValue(newValue);
        props.onChange?.(name, newValue);
      }}
    />
  );
};

