// Form-backed wrapper: the form-builder owns value and validity, so the field only needs the formField
// and an onChange that forwards to handleFieldOnChange. The form is built per mount so no state (refs,
// values) can leak between story renders.
const FormBackedInputField = (props: InputFieldProps) => {
  const [initialForm] = useState<Form>(() => ({
    fields: new Map<string, FormField>([
      [
        "email",
        buildField("email", { isRequired: true, validationType: "EMAIL", inputMode: "email", autoComplete: "email" }),
      ],
    ]),
  }));
  const [form, , handleFieldOnChange] = useForm(initialForm);
  return (
    <InputField
      {...props}
      formField={form.fields.get("email")}
      onChange={(name, value) => {
        handleFieldOnChange(name, value);
        props.onChange?.(name, value);
      }}
    />
  );
};

/** A required e-mail field driven by the form-builder (`useForm`). The play function types an invalid
 * address; the form-builder validates the field about a second after typing stops, so the story ends on
 * the real validation error. */
export const WithFormField: Story = {
  args: {
    name: "email",
    label: "E-postadress",
    placeholder: "namn@exempel.se",
  },
  render: (args) => <FormBackedInputField {...args} />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // The required marker is an inline span, so the computed accessible name has no space before the
    // parenthesis; match the label prefix instead of the exact concatenation.
    const input = canvas.getByRole("textbox", { name: /^E-postadress/ });
    await userEvent.type(input, "inte-en-mejl");
    await expect(input).toHaveValue("inte-en-mejl");
    // The form-builder debounces validation by one second, and the error then animates in.
    await waitFor(() => expect(canvas.getByText("Vänligen ange en giltig e-postadress")).toBeVisible(), {
      timeout: 3000,
    });
    await expect(input).toHaveAttribute("aria-invalid", "true");
  },
};

const onChangeSpy = fn();

export const TestPhoneSanitizing: Story = {
  args: {
    name: "mobileNumber",
    label: "Telefonnummer",
    placeholder: "073-000 00 00",
    formField: buildField("mobileNumber", { validationType: "PHONE", inputMode: "tel" }),
    onChange: onChangeSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    const canvas = within(canvasElement);
    const input = canvas.getByRole("textbox", { name: "Telefonnummer" });
    // The letter is stripped as it is typed; digits, spaces and hyphens are kept.
    await userEvent.type(input, "07a3-12 34");
    await expect(input).toHaveValue("073-12 34");
    await expect(onChangeSpy).toHaveBeenLastCalledWith("mobileNumber", "073-12 34");
  },
};
